      "description": ""
    },
    {
      "html": "<div style=\"padding:48px 24px;background:var(--color-parchment,#f5f5ee);font-family:var(--font-abc-arizona-sans,'Cormorant SC',Georgia,serif);max-width:600px;\">\n  <style>\n    :root {\n      --color-deep-ink:#192830;--color-parchment:#f5f5ee;--color-linen:#e4e7da;--color-pressed-cotton:#d7d7cb;--color-graphite:#2f3136;--color-slate:#535557;--color-dusk:#424e52;--color-white:#ffffff;--color-ink:#000000;--font-abc-arizona-sans:'Cormorant SC',Georgia,serif;--font-abc-arizona-flare:'Playfair Display','Cormorant Garamond',Georgia,serif;\n    }\n  </style>\n\n  <!-- Section heading -->\n  <div style=\"text-align:center;margin-bottom:40px;\">\n    <h2 style=\"font-family:var(--font-abc-arizona-flare,'Playfair Display','Cormorant Garamond',Georgia,serif);font-size:40px;font-weight:400;letter-spacing:-1.24px;line-height:1;color:var(--color-graphite,#2f3136);margin:0 0 16px 0;\">Effortless health logging for everyone</h2>\n    <p style=\"font-family:var(--font-abc-arizona-sans,'Cormorant SC',Georgia,serif);font-size:16px;font-weight:400;letter-spacing:-0.32px;line-height:1.4;color:var(--color-slate,#535557);margin:0 auto;max-width:480px;\">Use voice, text, photos, or connect to devices, apps, and medical portals to instantly record data—from health records and medications to meals and vitals for you and your whole family.</p>\n  </div>\n\n  <!-- Cards grid -->\n  <div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:16px;\">\n    <!-- Card 1: Natural Language -->\n    <div style=\"display:flex;flex-direction:column;\">\n      <div style=\"background:#9bb8c8;border-radius:6px;height:220px;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:24px;position:relative;overflow:hidden;\">\n        <div style=\"width:64px;height:64px;border-radius:9999px;background:#c4b9a8;border:3px solid var(--color-white,#ffffff);margin-bottom:8px;\"></div>\n        <span style=\"font-family:var(--font-abc-arizona-sans,'Cormorant SC',Georgia,serif);font-size:13px;color:var(--color-white,#ffffff);letter-spacing:-0.32px;\">Mom</span>\n        <div style=\"position:absolute;bottom:40px;left:20px;right:20px;border-top:1px dotted rgba(255,255,255,0.4);\"></div>\n        <div style=\"position:absolute;bottom:16px;left:20px;display:flex;align-items:center;gap:4px;\">\n          <span style=\"color:#c85c3a;font-family:var(--font-abc-arizona-flare,'Playfair Display',Georgia,serif);font-size:18px;font-weight:400;font-style:italic;\">/</span>\n          <span style=\"font-family:var(--font-abc-arizona-sans,'Cormorant SC',Georgia,serif);font-size:13px;color:rgba(255,255,255,0.7);letter-spacing:-0.32px;\">weigh</span>\n        </div>\n      </div>\n      <div style=\"padding:12px 0 0 0;text-align:center;\">\n        <p style=\"font-family:var(--font-abc-arizona-sans,'Cormorant SC',Georgia,serif);font-size:12px;font-weight:400;letter-spacing:0.5px;line-height:1;color:var(--color-graphite,#2f3136);margin:0 0 4px 0;text-transform:uppercase;\">Natural Language</p>\n        <p style=\"font-family:var(--font-abc-arizona-sans,'Cormorant SC',Georgia,serif);font-size:13px;font-weight:400;letter-spacing:-0.32px;line-height:1.3;color:var(--color-slate,#535557);margin:0;\">Easily log with voice or text.</p>\n      </div>\n    </div>\n\n    <!-- Card 2: Vision -->\n    <div style=\"display:flex;flex-direction:column;\">\n      <div style=\"background:#8a9088;border-radius:6px;height:220px;display:flex;align-items:center;justify-content:center;padding:24px;position:relative;overflow:hidden;\">\n        <div style=\"width:100px;height:100px;border-radius:9999px;background:#6b7a5e;border:2px solid rgba(255,255,255,0.5);\"></div>\n        <!-- Viewfinder corners -->\n        <div style=\"position:absolute;top:40px;left:30px;width:20px;height:20px;border-left:2px solid rgba(255,255,255,0.6);border-top:2px solid rgba(255,255,255,0.6);\"></div>\n        <div style=\"position:absolute;top:40px;right:30px;width:20px;height:20px;border-right:2px solid rgba(255,255,255,0.6);border-top:2px solid rgba(255,255,255,0.6);\"></div>\n        <div style=\"position:absolute;bottom:40px;left:30px;width:20px;height:20px;border-left:2px solid rgba(255,255,255,0.6);border-bottom:2px solid rgba(255,255,255,0.6);\"></div>\n        <div style=\"position:absolute;bottom:40px;right:30px;width:20px;height:20px;border-right:2px solid rgba(255,255,255,0.6);border-bottom:2px solid rgba(255,255,255,0.6);\"></div>\n      </div>\n      <div style=\"padding:12px 0 0 0;text-align:center;\">\n        <p style=\"font-family:var(--font-abc-arizona-sans,'Cormorant SC',Georgia,serif);font-size:12px;font-weight:400;letter-spacing:0.5px;line-height:1;color:var(--color-graphite,#2f3136);margin:0 0 4px 0;text-transform:uppercase;\">Vision</p>\n        <p style=\"font-family:var(--font-abc-arizona-sans,'Cormorant SC',Georgia,serif);font-size:13px;font-weight:400;letter-spacing:-0.32px;line-height:1.3;color:var(--color-slate,#535557);margin:0;\">Take photos to log meals, medications, and more.</p>\n      </div>\n    </div>\n\n    <!-- Card 3: Connect -->\n    <div style=\"display:flex;flex-direction:column;\">\n      <div style=\"background:var(--color-linen,#e4e7da);border-radius:6px;height:220px;display:flex;flex-direction:column;align-items:flex-start;justify-content:center;padding:20px;gap:10px;\">\n        <div style=\"display:flex;align-items:center;gap:8px;opacity:0.5;\">\n          <div style=\"width:18px;height:18px;border-radius:4px;background:var(--color-pressed-cotton,#d7d7cb);\"></div>\n          <span style=\"font-family:var(--font-abc-arizona-sans,'Cormorant SC',Georgia,serif);font-size:13px;color:var(--color-slate,#535557);letter-spacing:-0.32px;\">Medical Records</span>\n        </div>\n        <div style=\"display:flex;align-items:center;gap:8px;\">\n          <div style=\"width:18px;height:18px;border-radius:4px;background:#c85c3a;\"></div>\n          <span style=\"font-family:var(--font-abc-arizona-sans,'Cormorant SC',Georgia,serif);font-size:14px;color:var(--color-graphite,#2f3136);letter-spacing:-0.35px;font-weight:400;\">Lab Test</span>\n        </div>\n        <div style=\"display:flex;align-items:center;gap:8px;\">\n          <div style=\"width:18px;height:18px;border-radius:4px;background:var(--color-graphite,#2f3136);\"></div>\n          <span style=\"font-family:var(--font-abc-arizona-sans,'Cormorant SC',Georgia,serif);font-size:15px;color:var(--color-graphite,#2f3136);letter-spacing:-0.32px;font-weight:400;\">Apple Health</span>\n        </div>\n        <div style=\"display:flex;align-items:center;gap:8px;\">\n          <div style=\"width:18px;height:18px;border-radius:4px;background:#5a8a6a;\"></div>\n          <span style=\"font-family:var(--font-abc-arizona-sans,'Cormorant SC',Georgia,serif);font-size:14px;color:var(--color-graphite,#2f3136);letter-spacing:-0.35px;\">Vaccine Records</span>\n        </div>\n        <div style=\"display:flex;align-items:center;gap:8px;margin-top:4px;opacity:0.4;\">\n          <div style=\"width:36px;height:16px;border-radius:3px;background:var(--color-dusk,#424e52);\"></div>\n          <span style=\"font-family:var(--font-abc-arizona-sans,'Cormorant SC',Georgia,serif);font-size:12px;color:var(--color-slate,#535557);letter-spacing:-0.32px;\">fitbit</span>\n        </div>\n      </div>\n      <div style=\"padding:12px 0 0 0;text-align:center;\">\n        <p style=\"font-family:var(--font-abc-arizona-sans,'Cormorant SC',Georgia,serif);font-size:12px;font-weight:400;letter-spacing:0.5px;line-height:1;color:var(--color-graphite,#2f3136);margin:0 0 4px 0;text-transform:uppercase;\">Connect</p>\n        <p style=\"font-family:var(--font-abc-arizona-sans,'Cormorant SC',Georgia,serif);font-size:13px;font-weight:400;letter-spacing:-0.32px;line-height:1.3;color:var(--color-slate,#535557);margin:0;\">Integrate with apps and wearables.</p>\n      </div>\n    </div>\n  </div>\n</div>",
